const r = await fetch('/api/payments/methods', {
  method: 'POST',
  headers: { Authorization: 'Bearer ' + jwt, 'Content-Type': 'application/json' },
  body: JSON.stringify({ provider_token: stripeToken, label: 'Acme Visa' }),
});
const { payment_method_id } = (await r.json()).data;

import { charge } from '@projexlight/sdk-payment';
const res = await charge({
  tenant_id, payment_method_id, amount_cents: invoice.total_cents, currency: 'usd',
  idempotency_key: `invoice:${invoice.invoice_id}`,
});

await fetch(`/api/payments/${charge_id}/refund`, {
  method: 'POST', headers: { Authorization: 'Bearer ' + jwt },
  body: JSON.stringify({ amount_cents: 1500, reason: 'partial-credit' }),
});

await fetch(`/api/payments/${charge_id}/distribute`, {
  method: 'POST', body: JSON.stringify({
    splits: [
      { party_id: 'acct_reseller', amount_cents: 1500 },
      { party_id: 'acct_seller_a', amount_cents: 7000 },
      { party_id: 'acct_platform_fee', amount_cents: 500 },
    ],
  }),
});
